// Calcula hash SHA256 do conteudo
const crypto = require('crypto');
const post = $input.first().json;

const content = (post.content_html || post.content || '') + (post.title || '');
const contentHash = crypto.createHash('sha256').update(content).digest('hex');

return [{
  json: {
    ...post,
    content_hash: contentHash
  }
}];

// Smart Markdown Chunker - Respeita hierarquia do documento

const CONFIG = {
  MIN_CHUNK_SIZE: 400,
  TARGET_CHUNK_SIZE: 600,
  MAX_CHUNK_SIZE: 800,
  MAX_HEADING_LENGTH: 200,
  CHARS_PER_TOKEN: 4
};

class HierarchyNode {
  constructor(title, level) {
    this.title = title;
    this.level = level;
  }
}

class SmartMarkdownChunker {
  constructor(config) {
    this.config = config;
    this.chunks = [];
    this.hierarchyStack = [];
  }

  detectHeading(line) {
    const match = line.match(/^(#{1,6})\\s+(.+)$/);
    if (match) {
      return {
        level: match[1].length,
        title: match[2].trim().substring(0, this.config.MAX_HEADING_LENGTH)
      };
    }
    return null;
  }

  updateHierarchy(level, title) {
    while (this.hierarchyStack.length > 0 &&
           this.hierarchyStack[this.hierarchyStack.length - 1].level >= level) {
      this.hierarchyStack.pop();
    }
    this.hierarchyStack.push(new HierarchyNode(title, level));
  }

  getHierarchyPath() {
    return this.hierarchyStack.map(n => n.title).join(' > ');
  }

  estimateTokens(text) {
    return Math.ceil(text.length / this.config.CHARS_PER_TOKEN);
  }

  chunk(markdown, metadata = {}) {
    const lines = markdown.split('\\n');
    let currentChunk = { content: '', tokens: 0, headings: [] };

    this.chunks = [];
    this.hierarchyStack = [];
    let chunkIndex = 0;

    const saveChunk = () => {
      if (currentChunk.content.trim()) {
        this.chunks.push({
          chunk_index: chunkIndex++,
          chunk_text: currentChunk.content.trim(),
          chunk_tokens: currentChunk.tokens,
          hierarchy_path: this.getHierarchyPath(),
          headings_in_chunk: currentChunk.headings,
          metadata: {
            ...metadata,
            hierarchy_stack: JSON.parse(JSON.stringify(this.hierarchyStack)),
            chunk_position: this.chunks.length === 0 ? 'start' : 'middle'
          }
        });
      }
      currentChunk = { content: '', tokens: 0, headings: [] };
    };

    for (const line of lines) {
      const heading = this.detectHeading(line);
      const lineTokens = this.estimateTokens(line);

      if (heading) {
        if (currentChunk.tokens >= this.config.TARGET_CHUNK_SIZE) {
          saveChunk();
        }
        this.updateHierarchy(heading.level, heading.title);
        currentChunk.headings.push({
          level: heading.level,
          title: heading.title,
          path: this.getHierarchyPath()
        });
      }

      currentChunk.content += (currentChunk.content ? '\\n' : '') + line;
      currentChunk.tokens += lineTokens;

      if (currentChunk.tokens >= this.config.MAX_CHUNK_SIZE) {
        saveChunk();
      }
    }

    saveChunk();

    if (this.chunks.length > 0) {
      this.chunks[this.chunks.length - 1].metadata.chunk_position = 'end';
    }

    this.addRanges();
    return this.chunks;
  }

  addRanges() {
    const totalChunks = this.chunks.length;
    for (let i = 0; i < totalChunks; i++) {
      const chunk = this.chunks[i];
      const currentPath = chunk.hierarchy_path;
      let sectionStart = i;
      let sectionEnd = i;
      const rootSection = currentPath.split(' > ')[0];

      for (let j = i - 1; j >= 0; j--) {
        if (this.chunks[j].hierarchy_path.startsWith(rootSection)) {
          sectionStart = j;
        } else {
          break;
        }
      }

      for (let j = i + 1; j < totalChunks; j++) {
        if (this.chunks[j].hierarchy_path.startsWith(rootSection)) {
          sectionEnd = j;
        } else {
          break;
        }
      }

      chunk.section_range = [sectionStart, sectionEnd];
      chunk.parent_range = [0, totalChunks - 1];
    }
  }
}

// === Processamento ===
const post = $('CHECK HASH').first().json;

// Remove HTML e limpa texto
const cleanText = (post.content_html || post.content || '')
  .replace(/<[^>]+>/g, '')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .trim();

const metadata = {
  doc_id: post.id,
  doc_name: post.title,
  source_type: 'post',
  tier: post.tier,
  created_at: post.created_at,
  content_hash: post.content_hash
};

const chunker = new SmartMarkdownChunker(CONFIG);
const chunks = chunker.chunk(cleanText, metadata);

return chunks.map(chunk => ({ json: { ...chunk, post_id: post.id } }));

// Prepara array de textos para batch embedding
const items = $input.all();
const texts = items.map(item => item.json.chunk_text);

return [{
  json: {
    texts: texts,
    items: items.map(i => i.json)
  }
}];

// Combina chunks com seus embeddings
const response = $json;
const preparedData = $('PREPARAR EMBEDDINGS').first().json;

const embeddings = response.data;
const items = preparedData.items;

const results = items.map((item, i) => ({
  json: {
    source_type: item.metadata.source_type,
    source_id: item.metadata.doc_id,
    chunk_index: item.chunk_index,
    chunk_text: item.chunk_text,
    chunk_tokens: item.chunk_tokens,
    embedding: embeddings[i].embedding,
    hierarchy_path: item.hierarchy_path,
    section_range: item.section_range,
    parent_range: item.parent_range,
    headings_in_chunk: item.headings_in_chunk,
    metadata: item.metadata,
    content_hash: item.metadata.content_hash,
    is_active: true
  }
}));

return results;

// Prepara dados para o record manager
const firstChunk = $('COMBINAR EMBEDDINGS').first().json;
const allChunks = $('COMBINAR EMBEDDINGS').all();

return [{
  json: {
    doc_id: firstChunk.source_id,
    doc_name: firstChunk.metadata.doc_name,
    source_type: firstChunk.source_type,
    content_hash: firstChunk.content_hash,
    version: 1,
    chunk_count: allChunks.length,
    status: 'complete',
    indexed_at: new Date().toISOString()
  }
}];
